#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Values are remembered between runs here (usernames only; no passwords or tokens are stored).
ENV_FILE="${ENV_FILE:-$HOME/.config/hyprdial-publish.env}"
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO_URL="https://github.com/mvp-mark/hyprdial"

run_wizard() {

TOTAL_STAGES=8
VERSION=$(sed -n 's/^__version__ = "\(.*\)"/\1/p' "$ROOT/hyprdial/__init__.py")

banner "Publish Hyprdial $VERSION on the AUR, COPR (Fedora) and OBS (openSUSE)"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "AUR: account"
if ! curl -fsSI "$REPO_URL/archive/refs/tags/v$VERSION.tar.gz" >/dev/null; then
  warn "The tag v$VERSION isn't on GitHub yet; release it first (git tag + push), then run this again."
  exit 1
fi
say "The AUR is where Arch users find packages built from source (yay -S hyprdial)."
open_url "https://aur.archlinux.org/register"
step "Fill in a user name and your e-mail, solve the captcha and click Create."
step "Open the e-mail from the AUR and set your password with the link in it."
note "Already have an account? Just log in."
ask AUR_USER "Your AUR user name:"
write_env AUR_USER "$AUR_USER"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "AUR: SSH key"
say "The AUR receives packages over SSH, with your existing key ~/.ssh/id_ed25519."
if [[ ! -f "$HOME/.ssh/id_ed25519.pub" ]]; then
  warn "No ~/.ssh/id_ed25519.pub; create one with: ssh-keygen -t ed25519"
  exit 1
fi
if command -v wl-copy >/dev/null 2>&1; then
  wl-copy < "$HOME/.ssh/id_ed25519.pub"
  note "Your PUBLIC key is in the clipboard (only the .pub file; the private key never leaves your computer)."
else
  say "Copy this PUBLIC key:"; note "$(cat "$HOME/.ssh/id_ed25519.pub")"
fi
open_url "https://aur.archlinux.org/account/$AUR_USER/edit"
step "Paste it into 'SSH Public Key', type your current password at the bottom and click Update."
pause "Done? Press Enter to test the connection."
until ssh -o BatchMode=yes aur@aur.archlinux.org help >/dev/null 2>&1; do
  warn "The AUR doesn't accept the key yet."
  pause "Check the key on the AUR page, then press Enter to try again (Ctrl-C to stop)."
done
say "${GREEN}✓${RESET} The AUR knows your key."

# ── 3 ────────────────────────────────────────────────────────────────────
stage "AUR: publish"
say "This builds the package from the v$VERSION tarball to make sure it works, then pushes the PKGBUILD to"
say "https://aur.archlinux.org/packages/hyprdial. Anyone can see and install it from then on."
if confirm "Publish hyprdial $VERSION on the AUR now?"; then
  (cd "$ROOT" && git pull --ff-only -q || true)  # the release workflow pins the checksum on main
  "$ROOT/packaging/arch/publish-aur.sh"
  pause "Press Enter to go on."
else
  SKIPPED+=("AUR: run packaging/arch/publish-aur.sh")
fi

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Fedora: account"
say "COPR builds RPMs for Fedora. It signs in with a Fedora account."
open_url "https://accounts.fedoraproject.org/"
step "Click 'Register', choose a user name, confirm the e-mail and set a password."
note "Already have a Fedora account? Skip this."
ask FAS_USER "Your Fedora user name:"
write_env FAS_USER "$FAS_USER"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "COPR: project and package"
open_url "https://copr.fedorainfracloud.org/coprs/$FAS_USER/"
step "Log in (top right) with the Fedora account if asked, then click 'New Project'."
step "Project name: hyprdial. Under Chroots tick fedora-rawhide-x86_64 and the newest fedora-NN-x86_64."
step "Leave the rest as it is and click Create."
pause "Created? Press Enter."
open_url "https://copr.fedorainfracloud.org/coprs/$FAS_USER/hyprdial/packages/"
step "Click 'New package' and choose the SCM source type."
step "Package name: hyprdial."
step "Clone url: $REPO_URL"
step "Spec File: packaging/rpm/hyprdial.spec"
step "Source build method: make srpm (it uses .copr/Makefile from the repository)."
step "Tick 'Auto-rebuild', then click Save."
note "If a field has another name on the page, look for the one with the same meaning: COPR changes its forms now and then."
pause "Saved? Press Enter."
open_url "https://copr.fedorainfracloud.org/coprs/$FAS_USER/hyprdial/packages/"
step "Click 'Rebuild' on the hyprdial row and submit. The build takes a few minutes; it should end 'succeeded'."
pause "Started? Press Enter."

# ── 6 ────────────────────────────────────────────────────────────────────
stage "openSUSE: account"
say "OBS (the openSUSE Build Service) builds RPMs for openSUSE Tumbleweed."
open_url "https://build.opensuse.org/"
step "Click 'Sign Up' (top right), create the account and confirm the e-mail."
note "Already have an openSUSE account? Just log in."
ask OBS_USER "Your openSUSE user name:"
write_env OBS_USER "$OBS_USER"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "OBS: package"
open_url "https://build.opensuse.org/project/show/home:$OBS_USER"
step "Click 'Create Package'. Name: hyprdial; Title: Hyprdial; Description: Settings app for Hyprland. Click Create."
pause "Created? Press Enter."
open_url "https://build.opensuse.org/repositories/home:$OBS_USER"
step "If openSUSE Tumbleweed isn't listed: Add from a Distribution → tick openSUSE Tumbleweed."
pause "Done? Press Enter."
open_url "https://build.opensuse.org/package/show/home:$OBS_USER/hyprdial"
step "Click 'Add File' and upload, one at a time, from $ROOT/packaging/rpm:"
note "    hyprdial.spec"
note "    _service      (downloads the v$VERSION tarball from GitHub before each build)"
step "The build starts by itself; its state shows on the right of the package page."
pause "Uploaded? Press Enter."

# ── 8 ────────────────────────────────────────────────────────────────────
stage "Check and share"
say "When the builds are green, users install Hyprdial like this:"
note "  Arch:      yay -S hyprdial"
note "  Fedora:    sudo dnf copr enable $FAS_USER/hyprdial && sudo dnf install hyprdial"
note "  openSUSE:  sudo zypper addrepo https://download.opensuse.org/repositories/home:$OBS_USER/openSUSE_Tumbleweed/home:$OBS_USER.repo"
note "             sudo zypper install hyprdial"
say "Tell Claude these user names, so the README gets these lines:"
note "  AUR: $AUR_USER   Fedora: $FAS_USER   openSUSE: $OBS_USER"
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
